export function onQueryChange(callback: (query: string) => void): (query: string) => void {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return (query: string) => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => callback(query), /* TODO: debounce delay in ms */ 0);
  };
}

